WITH "__duckstream_0" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c5 AS c4, t.c8 AS c5, t.c10 AS c6, t.c11 AS c7, t.c12 AS c8, t.c14 AS c9, t.c15 AS c10, t.c16 AS c11 FROM (SELECT t.c11 AS c0, t.c12 AS c1, t.c13 AS c2, t.c14 AS c3, t.c0 AS c4, t.c1 AS c5, t.c15 AS c6, t.c16 AS c7, t.c2 AS c8, t.c3 AS c9, t.c4 AS c10, t.c5 AS c11, t.c6 AS c12, t.c7 AS c13, t.c8 AS c14, t.c9 AS c15, t.c10 AS c16 FROM (SELECT t.c15 AS c0, t.c16 AS c1, t.c0 AS c2, t.c1 AS c3, t.c2 AS c4, t.c3 AS c5, t.c4 AS c6, t.c5 AS c7, t.c6 AS c8, t.c7 AS c9, t.c8 AS c10, t.c9 AS c11, t.c10 AS c12, t.c11 AS c13, t.c12 AS c14, t.c13 AS c15, t.c14 AS c16 FROM (SELECT t.c2 AS c0, t.c3 AS c1, t.c4 AS c2, t.c5 AS c3, t.c6 AS c4, t.c7 AS c5, t.c8 AS c6, t.c9 AS c7, t.c10 AS c8, t.c11 AS c9, t.c12 AS c10, t.c13 AS c11, t.c14 AS c12, t.c15 AS c13, t.c16 AS c14, t.c0 AS c15, t.c1 AS c16 FROM (SELECT l.c0 AS c0, l.c1 AS c1, r.c0 AS c2, r.c1 AS c3, r.c2 AS c4, r.c3 AS c5, r.c4 AS c6, r.c5 AS c7, r.c6 AS c8, r.c7 AS c9, r.c8 AS c10, r.c9 AS c11, r.c10 AS c12, r.c11 AS c13, r.c12 AS c14, r.c13 AS c15, r.c14 AS c16 FROM (SELECT "id" AS c0, "name" AS c1 FROM "source_team") l INNER JOIN (SELECT t.c6 AS c0, t.c7 AS c1, t.c8 AS c2, t.c9 AS c3, t.c10 AS c4, t.c11 AS c5, t.c12 AS c6, t.c13 AS c7, t.c14 AS c8, t.c0 AS c9, t.c1 AS c10, t.c2 AS c11, t.c3 AS c12, t.c4 AS c13, t.c5 AS c14 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, r.c0 AS c6, r.c1 AS c7, r.c2 AS c8, r.c3 AS c9, r.c4 AS c10, r.c5 AS c11, r.c6 AS c12, r.c7 AS c13, r.c8 AS c14 FROM (SELECT t.c2 AS c0, t.c3 AS c1, t.c4 AS c2, t.c5 AS c3, t.c0 AS c4, t.c1 AS c5 FROM (SELECT l.c0 AS c0, l.c1 AS c1, r.c0 AS c2, r.c1 AS c3, r.c2 AS c4, r.c3 AS c5 FROM (SELECT "id" AS c0, "phase_id" AS c1 FROM "source_stage_group") l INNER JOIN (SELECT "group_id" AS c0, "team_id" AS c1, "add_sub" AS c2, "bias" AS c3 FROM "source_team_group") r ON (l.c0 = r.c0)) t) l INNER JOIN (SELECT t.c4 AS c0, t.c5 AS c1, t.c6 AS c2, t.c7 AS c3, t.c8 AS c4, t.c0 AS c5, t.c1 AS c6, t.c2 AS c7, t.c3 AS c8 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, r.c0 AS c4, r.c1 AS c5, r.c2 AS c6, r.c3 AS c7, r.c4 AS c8 FROM (SELECT "id" AS c0, "point_win" AS c1, "point_draw" AS c2, "point_loss" AS c3 FROM "source_championship") l INNER JOIN (SELECT "id" AS c0, "championship_id" AS c1, "sort" AS c2, "bonus_points" AS c3, "bonus_points_threshold" AS c4 FROM "source_phase") r ON (l.c0 = r.c1)) t) r ON (r.c0 = l.c5)) t) r ON (l.c0 = r.c10)) t) t) t) t),
"__duckstream_1" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c12 AS c2, t.c14 AS c3, t.c15 AS c4, CASE WHEN (t.c17 = t.c1) THEN t.c18 ELSE t.c17 END AS c5, CASE WHEN (t.c17 = t.c1) THEN t.c19 ELSE t.c20 END AS c6, CASE WHEN (t.c17 = t.c1) THEN t.c20 ELSE t.c19 END AS c7, CASE WHEN (t.c17 = t.c1) THEN CAST(0 AS INTEGER) ELSE t.c20 END AS c8, COALESCE(CASE WHEN (t.c17 = t.c1) THEN t.c21 ELSE t.c22 END, CAST(0 AS INTEGER)) AS c9, COALESCE(CASE WHEN (t.c17 = t.c1) THEN t.c23 ELSE t.c24 END, CAST(0 AS INTEGER)) AS c10, t.c9 AS c11, t.c10 AS c12, t.c11 AS c13, t.c7 AS c14, t.c8 AS c15 FROM (SELECT l.c0 AS c0, l.c1 AS c1, l.c2 AS c2, l.c3 AS c3, l.c4 AS c4, l.c5 AS c5, l.c6 AS c6, l.c7 AS c7, l.c8 AS c8, l.c9 AS c9, l.c10 AS c10, l.c11 AS c11, r.c0 AS c12, r.c1 AS c13, r.c2 AS c14, r.c3 AS c15, r.c4 AS c16, r.c5 AS c17, r.c6 AS c18, r.c7 AS c19, r.c8 AS c20, r.c9 AS c21, r.c10 AS c22, r.c11 AS c23, r.c12 AS c24 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8, v.c9 AS c9, v.c10 AS c10, v.c11 AS c11 FROM "__duckstream_0" v) l INNER JOIN (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6, t.c7 AS c7, t.c8 AS c8, t.c9 AS c9, t.c10 AS c10, t.c11 AS c11, t.c12 AS c12 FROM (SELECT "id" AS c0, "phase_id" AS c1, "day" AS c2, "kickoff" AS c3, "played" AS c4, "home_id" AS c5, "away_id" AS c6, "home_score" AS c7, "away_score" AS c8, "home_aet" AS c9, "away_aet" AS c10, "home_pen" AS c11, "away_pen" AS c12 FROM "source_game") t WHERE t.c4) r ON ((r.c1 = l.c5) AND ((r.c5 = l.c1) OR (r.c6 = l.c1)))) t),
"__duckstream_2" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c5 AS c5, t.c6 AS c6, t.c7 AS c7, t.c8 AS c8, t.c9 AS c9, t.c10 AS c10, CAST(CASE WHEN (t.c6 > t.c7) THEN 'w' WHEN (t.c6 < t.c7) THEN 'l' ELSE 'd' END AS VARCHAR) AS c11, CASE WHEN (t.c6 > t.c7) THEN CAST((t.c11 + CASE WHEN ((t.c14 > CAST(0 AS INTEGER)) AND (CAST((t.c6 - t.c7) AS INTEGER) >= t.c15)) THEN t.c14 ELSE CAST(0 AS INTEGER) END) AS INTEGER) WHEN (t.c6 < t.c7) THEN t.c13 ELSE t.c12 END AS c12 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8, v.c9 AS c9, v.c10 AS c10, v.c11 AS c11, v.c12 AS c12, v.c13 AS c13, v.c14 AS c14, v.c15 AS c15 FROM "__duckstream_1" v) t),
"__duckstream_3" AS (SELECT t.c0 AS c0, t.c1 AS c1, t.c2 AS c2, t.c3 AS c3, t.c4 AS c4, t.c11 AS c5 FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5, v.c6 AS c6, v.c7 AS c7, v.c8 AS c8, v.c9 AS c9, v.c10 AS c10, v.c11 AS c11, v.c12 AS c12 FROM "__duckstream_2" v) t)
SELECT CAST(result.c0 AS VARCHAR) AS "group_id", CAST(result.c1 AS VARCHAR) AS "team_id", CAST(result.c2 AS VARCHAR) AS "id", CAST(result.c3 AS VARCHAR) AS "day", CAST(result.c4 AS VARCHAR) AS "kickoff", CAST(result.c5 AS VARCHAR) AS "result" FROM (SELECT v.c0 AS c0, v.c1 AS c1, v.c2 AS c2, v.c3 AS c3, v.c4 AS c4, v.c5 AS c5 FROM "__duckstream_3" v) result;
